+func TestDelWithHashCollision(t *testing.T) {
+	c := New(1024)
+	defer c.Reset()
+
+	// These two keys should have the same hash (this is just an example, 
+	// in practice we'd need to find real keys with the same hash)
+	key1 := []byte("key1")
+	key2 := []byte("key2")
+
+	// For demonstration purposes, let's manually set up a scenario where
+	// two different keys have the same hash
+	h := uint64(12345) // Simulated hash value
+	
+	// Set both keys with the same hash (simulating a hash collision)
+	// We'll directly access the bucket to simulate this
+	idx := h % bucketsCount
+	c.buckets[idx].Set(key1, []byte("value1"), h)
+	c.buckets[idx].Set(key2, []byte("value2"), h+ bucketsCount) // Same effective hash
+
+	// Verify both values exist
+	if v := c.Get(nil, key1); string(v) != "value1" {
+		t.Fatalf("Expected 'value1' for key1, got '%s'", string(v))
+	}
+	if v := c.Get(nil, key2); string(v) != "value2" {
+		t.Fatalf("Expected 'value2' for key2, got '%s'", string(v))
+	}
+
+	// Delete key1
+	c.Del(key1)
+
+	// key1 should no longer exist
+	if v := c.Get(nil, key1); len(v) != 0 {
+		t.Fatalf("Expected empty value for key1 after deletion, got '%s'", string(v))
+	}
+
+	// key2 should still exist (this would fail with the old implementation)
+	if v := c.Get(nil, key2); string(v) != "value2" {
+		t.Fatalf("Expected 'value2' for key2 after deleting key1, got '%s'", string(v))
+	}
+}
